import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, fin, idx, T, DUR, Camara, Contador, Textura, Profundidad, Brillo, Paso, seguir, enCamino, tono, Regla, Chip, Ondas, Destello, sacudida, golpe, Recorrido, Easing, interpolate, clamp, spring, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
// parada de camara que nunca deja ver el borde del fondo
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
// donde cae el punto (x,y) del mundo en pantalla bajo una parada de camara
const scr = (c: {x: number; y: number; zoom: number}, x: number, y: number) => ({x: 540 + (x - c.x) * c.zoom, y: 1000 + (y - c.y) * c.zoom});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const PIELES = [['#f3d2b0', '#e3b88e', '#c99a6e'], ['#e0a878', '#c98f5e', '#9c6a40'], ['#b57b52', '#8a5a36', '#5e3a22'], ['#7a4f2c', '#5e3a22', '#3d2414']];
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const sf = (p: string, s: string, o = 0, n = 1) => ({t: en(p, n) + o, s});

// ---------- piezas dibujadas ----------
const Moneda: React.FC<{x: number; y: number; k?: number; r?: number; c?: string; txt?: string; sombra?: boolean}> = ({x, y, k = 1, r = 0, c = GOLD, txt = '$', sombra = true}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    {sombra && <ellipse cy={52} rx={54} ry={12} fill="rgba(0,0,0,0.35)" />}
    <circle r={52} fill="#a87908" />
    <circle r={45} fill={c} stroke="#8a6a10" strokeWidth={4} />
    <circle r={33} fill="none" stroke="#fff3b0" strokeWidth={3} opacity={0.7} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={46} fill="#7a5a00">{txt}</text>
    <path d="M -38 -12 A 40 40 0 0 1 14 -40" stroke="rgba(255,255,255,0.7)" strokeWidth={6} fill="none" strokeLinecap="round" />
  </g>
);

const Bill: React.FC<{x: number; y: number; r?: number; k?: number; txt?: string; tint?: string; halo?: string; corte?: number}> = ({x, y, r = 0, k = 1, txt = '100', tint = '#b4d9a2', halo, corte = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    {halo && <ellipse rx={250} ry={170} fill={halo} opacity={0.4} />}
    <rect x={-146} y={-60} width={304} height={144} rx={14} fill="rgba(0,0,0,0.35)" />
    <rect x={-150} y={-70} width={300} height={140} rx={14} fill={tint} stroke="#3f6b3a" strokeWidth={5} />
    <rect x={-134} y={-54} width={268} height={108} rx={9} fill="none" stroke="#3f6b3a" strokeWidth={2.5} opacity={0.65} />
    <circle r={42} fill="rgba(255,255,255,0.35)" stroke="#3f6b3a" strokeWidth={3} />
    <text y={15} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={txt.length > 2 ? 32 : 46} fill="#2f5a2b">{txt}</text>
    <text x={-122} y={-28} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <text x={100} y={50} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#2f5a2b">$</text>
    <path d="M -150 -70 L 24 -70 L -56 70 L -150 70 Z" fill="rgba(255,255,255,0.16)" />
    {corte > 0 && <path d={`M ${-20 + corte * 6} -76 l 18 28 l -22 24 l 20 26 l -18 30 l 14 22`} stroke="#1a1a1a" strokeWidth={4} fill="none" opacity={cl(corte)} />}
  </g>
);

const Cartera: React.FC<{x: number; y: number; k?: number; r?: number; grosor?: number; oro?: boolean}> = ({x, y, k = 1, r = 0, grosor = 1, oro = false}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs>
      <linearGradient id="cuero" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient>
    </defs>
    <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
    {[0, 1, 2].map((i) => <rect key={i} x={-150 + i * 26} y={-150 - 62 * grosor * (1 - i * 0.12)} width={250} height={90 * grosor + 20} rx={8} fill={['#b4d9a2', '#a3cf92', '#c1e2b2'][i]} stroke="#3f6b3a" strokeWidth={3} transform={`rotate(${(i - 1) * 4})`} />)}
    <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero)" stroke="#2c180a" strokeWidth={5} />
    <rect x={-170} y={-100} width={340} height={210} rx={20} fill="none" stroke={oro ? GOLD : '#c9a074'} strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
    <path d="M -190 -40 Q 0 -10 190 -40 L 190 -80 Q 0 -110 -190 -80 Z" fill="rgba(255,255,255,0.10)" />
    <rect x={120} y={-24} width={70} height={64} rx={14} fill={oro ? GOLD : '#7a4c28'} stroke="#2c180a" strokeWidth={4} />
    <circle cx={152} cy={8} r={12} fill={oro ? '#fff2b0' : '#c9a074'} />
  </g>
);

// mano con el dedo indice arriba; piel = 0 clara, 1 canela, 2 morena, 3 oscura
const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; piel?: number}> = ({x, y, r = 0, k = 1, dedo = true, piel = 1}) => {
  const C = PIELES[piel];
  const F = `url(#pl${piel})`;
  const L = C[2];
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs><linearGradient id={`pl${piel}`} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor={C[0]} /><stop offset="55%" stopColor={C[1]} /><stop offset="100%" stopColor={C[2]} /></linearGradient></defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
    </g>
  );
};

const Polvo: React.FC<{n?: number; color?: string; vel?: number}> = ({n = 30, color = 'rgba(255,240,210,0.5)', vel = 1}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 34;
        const y = (((h(i * 7 + 2) * 1920 - s * (14 + h(i) * 26) * vel) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.25 + h(i * 11) * 0.4} />;
      })}
    </svg>
  );
};

// celular de frente; lo que lleva dentro se dibuja en coordenadas locales (pantalla: x -166..166, y -350..350)
const Cel: React.FC<{x: number; y: number; k?: number; r?: number; luz?: string; children?: React.ReactNode}> = ({x, y, k = 1, r = 0, luz = '#0d1a2b', children}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <defs><clipPath id="clpCel"><rect x={-166} y={-350} width={332} height={700} rx={34} /></clipPath></defs>
    <rect x={-180} y={-362} width={380} height={760} rx={52} fill="rgba(0,0,0,0.38)" />
    <rect x={-190} y={-380} width={380} height={760} rx={52} fill="#14161c" stroke="#4a5060" strokeWidth={6} />
    <rect x={-166} y={-350} width={332} height={700} rx={34} fill={luz} />
    <g clipPath="url(#clpCel)">{children}</g>
    <rect x={-46} y={-346} width={92} height={20} rx={10} fill="#05060a" />
    <path d="M -190 -380 L -70 -380 L -190 -110 Z" fill="rgba(255,255,255,0.07)" />
  </g>
);

// burbuja de chat (local del celular o del mundo)
const Burb: React.FC<{x: number; y: number; txt: string; w?: number; mio?: boolean; a?: number; fs?: number; color?: string}> = ({x, y, txt, w = 250, mio = false, a = 1, fs = 30, color}) => (
  <g transform={`translate(${x} ${y}) scale(${0.7 + 0.3 * a})`} opacity={a}>
    <rect x={-w / 2} y={-30} width={w} height={60} rx={26} fill={color ?? (mio ? '#3b82f6' : '#e9edf3')} />
    <text y={11} textAnchor="middle" fontFamily={FONT} fontWeight={700} fontSize={fs} fill={mio ? '#fff' : '#1b2330'}>{txt}</text>
  </g>
);

// hoja de papel
const Papel: React.FC<{x: number; y: number; w: number; hh: number; r?: number; fill?: string; borde?: string; children?: React.ReactNode}> = ({x, y, w, hh, r = 0, fill = '#f4efe3', borde = '#b9ad8f', children}) => (
  <g transform={`translate(${x} ${y}) rotate(${r})`}>
    <rect x={-w / 2 + 8} y={-hh / 2 + 14} width={w} height={hh} rx={12} fill="rgba(0,0,0,0.38)" />
    <rect x={-w / 2} y={-hh / 2} width={w} height={hh} rx={12} fill={fill} stroke={borde} strokeWidth={4} />
    {children}
  </g>
);

// sello redondo o rectangular con texto
const Sello: React.FC<{x: number; y: number; txt: string; r?: number; k?: number; color?: string; w?: number}> = ({x, y, txt, r = -8, k = 1, color = RED, w = 360}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <rect x={-w / 2} y={-52} width={w} height={104} rx={14} fill="none" stroke={color} strokeWidth={9} />
    <rect x={-w / 2 + 10} y={-42} width={w - 20} height={84} rx={9} fill="none" stroke={color} strokeWidth={3} />
    <text y={20} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={58} fill={color}>{txt}</text>
  </g>
);

// etiqueta de precio con cordon
const Etq: React.FC<{x: number; y: number; txt: string; r?: number; k?: number; color?: string}> = ({x, y, txt, r = 0, k = 1, color = '#f6ecd2'}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <path d="M 0 -150 Q -30 -100 0 -60" stroke="#8a6a10" strokeWidth={5} fill="none" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill="rgba(0,0,0,0.3)" transform="translate(8 10)" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill={color} stroke="#b79a52" strokeWidth={5} />
    <circle cy={-34} r={11} fill="#3a2a00" />
    <text y={46} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={56} fill="#6b5524">{txt}</text>
  </g>
);

// ---------- caja registradora (cajon abierto = abre 0..1) ----------
const Caja: React.FC<{abre: number; luz?: number}> = ({abre, luz = 0}) => {
  const ty = 1360 + abre * 300;
  return (
    <g>
      <defs>
        <linearGradient id="metalC" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#4d535b" /><stop offset="25%" stopColor="#c9ced4" /><stop offset="55%" stopColor="#8e949c" /><stop offset="80%" stopColor="#d9dde2" /><stop offset="100%" stopColor="#474c54" /></linearGradient>
        <radialGradient id="luzC" cx="50%" cy="40%" r="60%"><stop offset="0%" stopColor="#fff2b0" /><stop offset="45%" stopColor={GOLD} /><stop offset="100%" stopColor="#6a4a08" /></radialGradient>
      </defs>
      <ellipse cx={540} cy={1700} rx={470} ry={40} fill="rgba(0,0,0,0.45)" />
      <polygon points={`150,1360 930,1360 ${990},${ty} 90,${ty}`} fill={luz > 0.02 ? 'url(#luzC)' : '#1b222b'} opacity={abre > 0.01 ? 1 : 0} />
      {abre > 0.01 && [0, 1, 2, 3].map((i) => <line key={i} x1={240 + i * 190} y1={1360} x2={210 + i * 205} y2={ty} stroke="rgba(0,0,0,0.5)" strokeWidth={5} />)}
      <rect x={110} y={760} width={860} height={600} rx={44} fill="url(#metalC)" stroke="#2d3137" strokeWidth={6} />
      <rect x={190} y={810} width={700} height={130} rx={18} fill="#0b1a12" stroke="#2d3137" strokeWidth={5} />
      <text x={850} y={915} textAnchor="end" fontFamily={FONT} fontWeight={800} fontSize={92} fill="#35ff6a">{luz > 0.5 ? '$80.00' : '0.00'}</text>
      {Array.from({length: 12}).map((_, i) => <rect key={i} x={230 + (i % 4) * 160} y={985 + Math.floor(i / 4) * 105} width={130} height={80} rx={16} fill={i === 11 ? GOLD : '#2c333c'} stroke="#12161b" strokeWidth={4} />)}
      <rect x={90} y={ty} width={900} height={110} rx={22} fill="url(#metalC)" stroke="#2d3137" strokeWidth={6} />
      <rect x={440} y={ty + 40} width={200} height={26} rx={13} fill="#10151c" />
    </g>
  );
};

// ---------- tiempos (todo atado a palabras del guion) ----------
const GANANCIA = en('ganancia'), TIENDA = en('tienda'), OFRECEN = en('ofrecen'), PAGAR = en('pagar');
const COMPRAS = en('compras'), TELEVISOR = en('televisor'), CAJA = en('caja'), OCHENTA = en('ochenta'), PROTEGES = en('proteges'), TRES = en('tres'), ANOS = en('anos');
const SUENA = en('suena'), CUIDADO = en('cuidado'), PERO = en('pero'), DONDE = en('donde'), OCH2 = en('ochenta', 2);
const SEGUN = en('segun'), MITAD = en('mitad'), DOS = en('dos'), TERCIOS = en('tercios'), GARANT = en('garantias'), COMO = en('como'), GAN2 = en('ganancia', 2);
const TUS = en('tus'), CUARENTA = en('cuarenta'), CINCUENTA = en('cincuenta'), SOLO = en('solo'), PARTE = en('parte'), REPARAR = en('reparar');
const Y4 = en('y', 4), PORQUE = en('porque'), MUCHOS = en('muchos'), FALLAN = en('fallan'), PRONTO = en('pronto'), FABRICANTE = en('fabricante'), GRATIS = en('gratis');
const ANTES = en('antes'), MIRA = en('mira'), CUBRE = en('cubre'), REPARACION = en('reparacion'), GUARDA = en('guarda'), IMPREVISTO = en('imprevisto');
const DALE = en('dale'), GRACIAS = en('gracias'), COMPRAR = en('comprar');

// ================= SITIO A: el cajon se abre y el billete entra (E1) =================
const A_CAM = [P(0, 540, 1000, 1.0), P(GANANCIA - 0.3, 540, 1250, 1.2), P(COMPRAS + 0.3, 540, 1400, 1.4)];
const A_END = A_CAM[2];
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const abre = cl(spr(-0.25, 9, 170));
  const q = enCamino(s, [[1300, 420], [1000, 820], [540, 1180], [540, 1500]], -0.35, 0.95);
  const luz = ro(s, GANANCIA - 0.05, GANANCIA + 0.5);
  return (
    <AbsoluteFill>
      <Camara paradas={A_CAM}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 55%, #3c4654 0%, #1b212b 62%, #090b10 100%)" linea="rgba(200,220,255,0.2)" luz="rgba(255,255,255,0.10)" semilla={3} />
        <Brillo x={540} y={1380} r={560 + 200 * luz} color={`rgba(255,200,61,${0.12 + 0.4 * luz})`} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <Caja abre={abre} luz={luz} />
          <g opacity={s < 1.05 ? 1 : 0}>
            <Bill x={q.x} y={q.y} r={(1 - q.p) * 330} k={1.25 - 0.4 * q.p} txt="80" halo="rgba(255,200,61,0.8)" />
          </g>
          {s >= 1.05 && <Bill x={540} y={1500} k={0.85} txt="80" halo={`rgba(255,200,61,${0.5 + 0.4 * luz})`} />}
          {[0, 1, 2, 3, 4, 5].map((i) => {
            const a = ro(s, GANANCIA + 0.05 + i * 0.07, GANANCIA + 0.7 + i * 0.07);
            return a > 0 && a < 1 ? <circle key={i} cx={540 + Math.cos(i * 1.05) * 300 * a} cy={1500 + Math.sin(i * 1.05) * 210 * a - 80 * a} r={10 * (1 - a) + 3} fill={GOLD} opacity={1 - a} /> : null;
          })}
        </svg>
        <Ondas x={540} y={1480} t0={GANANCIA} color={GOLD} radio={520} />
        <Chip texto="$80" x={540} y={980} t0={GANANCIA} t1={COMPRAS} color={RED} size={92} />
      </Camara>
    </AbsoluteFill>
  );
};

// ================= SITIO B: mostrador, la caja del tele y el billete que duda (E2 y E3) =================
const B_CAM = [P(COMPRAS - 0.4, 540, 1000, 1.0), P(CAJA, 460, 1050, 1.15), P(OCHENTA, 560, 1000, 1.2), P(SUENA + 0.3, 540, 1000, 1.25), P(CUIDADO + 0.8, 700, 980, 1.35), P(DONDE, 380, 980, 1.35), P(SEGUN - 0.1, 540, 1000, 1.45)];
const B_END = B_CAM[6];
const BILL_B = {x: 540, y: 900};
const SitioB: React.FC = () => {
  const {s, spr} = useS();
  const kTV = spr(COMPRAS + 0.05, 7, 110);
  const tvY = 1190 - (1 - kTV) * 1500;
  const sale = eio(ro(s, SUENA - 0.25, SUENA + 0.5));
  const mx = 1250 - 440 * eo(ro(s, CAJA - 0.1, CAJA + 0.6)) + sale * 700;
  const gira = Math.cos(s * 2.4) * 0.9 + (s > SUENA ? 0.1 : 0);
  const sube = eo(ro(s, SUENA - 0.1, SUENA + 0.9));
  const tiembla = golpe(s, DONDE, 14, 4) * 14;
  return (
    <AbsoluteFill>
      <Camara paradas={B_CAM}>
        <Textura tipo="fibra" base="linear-gradient(180deg, #d9e3f0 0%, #aebfd4 52%, #4a586c 100%)" linea="rgba(255,255,255,0.35)" luz="rgba(255,255,255,0.35)" semilla={5} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <rect x={0} y={1180} width={1080} height={740} fill="#7d8da3" />
          <rect x={0} y={1180} width={1080} height={26} fill="#dfe8f3" />
          {Array.from({length: 12}).map((_, i) => <line key={i} x1={0} x2={1080} y1={1240 + i * 58} y2={1240 + i * 58 + (h(i) - 0.5) * 8} stroke="rgba(255,255,255,0.12)" strokeWidth={3} />)}
          <g transform={`translate(${-sale * 900} 0)`}>
            <ellipse cx={440} cy={1196} rx={320} ry={26} fill="rgba(0,0,0,0.35)" opacity={kTV} />
            <rect x={170} y={tvY - 560} width={540} height={560} rx={10} fill="#c9a06a" stroke="#8a6a3a" strokeWidth={6} />
            <rect x={170} y={tvY - 560} width={540} height={70} fill="#b88d55" />
            <rect x={220} y={tvY - 440} width={440} height={270} rx={14} fill="#1a2434" stroke="#0a0f18" strokeWidth={6} />
            <path d={`M 230 ${tvY - 430} L 440 ${tvY - 430} L 300 ${tvY - 180} L 230 ${tvY - 180} Z`} fill="rgba(255,255,255,0.14)" />
            <text x={440} y={tvY - 90} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={66} fill="#5a3f1a">TV</text>
            <rect x={300} y={tvY - 70} width={280} height={14} rx={7} fill="#8a6a3a" />
          </g>
          <g transform={`translate(${mx} ${1330})`}>
            <Papel x={-70} y={-10} w={230} hh={310} r={-6} fill="#fff7e0" borde="#b9ad8f">
              <rect x={-90} y={-110} width={180} height={34} rx={8} fill={GOLD} />
              {[0, 1, 2, 3, 4].map((i) => <rect key={i} x={-90} y={-50 + i * 38} width={i % 2 ? 140 : 180} height={14} rx={7} fill="#c6bfa8" />)}
            </Papel>
            <Mano x={190} y={20} r={-90} k={0.62} piel={3} dedo={false} />
          </g>
          <g transform={`translate(0 ${(1 - sube) * 900})`} opacity={sube > 0 ? 1 : 0}>
            <Mano x={540} y={1240} r={0} k={0.95} piel={0} dedo={false} />
          </g>
          {s > SUENA - 0.2 && (
            <g transform={`translate(${BILL_B.x} ${BILL_B.y + 280 - sube * 280 + Math.sin(s * 3) * 12 + tiembla}) rotate(${Math.sin(s * 2) * 9 + 8})`}>
              <g transform={`scale(${Math.max(0.2, Math.abs(gira))} 1)`}>
                <Bill x={0} y={0} k={1.45} txt="80" halo="rgba(255,200,61,0.7)" />
              </g>
            </g>
          )}
        </svg>
        <Chip texto="$80" x={290} y={700} t0={OCHENTA} t1={SUENA - 0.1} color={GOLD} size={92} />
